<?php defined('BASEPATH') OR exit('No direct script access allowed');class Email_intel extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Email_mailbox_model','mailboxes');}function mailboxes(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(!$this->valid($d,TRUE))return;return $this->respond($this->mailboxes->save(NULL,$this->c['organizationId'],$d),201);}return $this->respond($this->mailboxes->all($this->c['organizationId']));}function mailbox($id){$m=$this->input->method(TRUE);if($m==='GET')$r=$this->mailboxes->one($id,$this->c['organizationId']);elseif($m==='DELETE')return $this->mailboxes->remove($id,$this->c['organizationId'])?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Mailbox not found',404);else{if(!$this->valid($d=$this->body(),FALSE))return;$r=$this->mailboxes->save($id,$this->c['organizationId'],$d);}return $r?$this->respond($r):$this->fail('NOT_FOUND','Mailbox not found',404);}function test($id){$r=$this->mailboxes->test($id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Mailbox not found',404);}private function valid($d,$create){if($create&&(!isset($d['name'],$d['emailAddress'])))return $this->fail('VALIDATION_ERROR','Name and email address required',422);if(isset($d['emailAddress'])&&!filter_var($d['emailAddress'],FILTER_VALIDATE_EMAIL)||isset($d['provider'])&&!in_array($d['provider'],array('gmail','outlook','custom','other'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid mailbox input',422);foreach(array('imapPort','smtpPort') as $p)if(isset($d[$p])&&($d[$p]<1||$d[$p]>65535))return $this->fail('VALIDATION_ERROR','Invalid mail server port',422);return TRUE;}function messages($id=NULL){$this->load->model('Email_message_model','messages');$m=$this->input->method(TRUE);if($m==='GET'){if($id){$r=$this->messages->one($id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Message not found',404);}return $this->respond($this->messages->listing($this->c['organizationId'],array('mailbox_id'=>$this->input->get('mailboxId'),'thread_id'=>$this->input->get('threadId'),'direction'=>$this->input->get('direction'))));}if($m==='DELETE')return $this->messages->remove($id,$this->c['organizationId'])?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Message not found',404);$d=$this->body();if($id){$r=$this->messages->update_message($id,$this->c['organizationId'],$d);return $r?$this->respond($r):$this->fail('NOT_FOUND','Message not found',404);}if(empty($d['mailboxId'])||!$this->mailboxes->one($d['mailboxId'],$this->c['organizationId'])||!filter_var($d['fromAddress']??'',FILTER_VALIDATE_EMAIL)||trim($d['bodyText']??'')==='')return $this->fail('VALIDATION_ERROR','Invalid email message',422);return $this->respond($this->messages->create($this->c['organizationId'],$d),201);}function threads($id=NULL){$this->load->model('Email_message_model','messages');if($id){$r=$this->messages->thread_detail($id,$this->c['organizationId']);if($r){$r['summary']=$this->messages->summarize($id,$this->c['organizationId']);$r['triage']=$this->messages->triage($id,$this->c['organizationId']);}return $r?$this->respond($r):$this->fail('NOT_FOUND','Thread not found',404);}return $this->respond($this->messages->threads($this->c['organizationId']));}function draft(){ $d=$this->body();if(trim($d['context']??'')==='')return $this->fail('VALIDATION_ERROR','Context required',422);$prompt='Draft a '.($d['length']??'medium').' '.($d['tone']??'professional').' email'.(!empty($d['recipient'])?' to '.$d['recipient']:'').'. Subject hint: '.($d['subjectHint']??'none')."\nContext: ".$d['context'];$this->load->library('Ai_provider');$r=$this->ai_provider->complete(array(array('role'=>'user','content'=>$prompt)));return $r['ok']?$this->respond(array('draftKind'=>'ai','draft'=>$r['content'],'modelId'=>$r['model'])):$this->fail($r['code'],$r['message'],503);}function summarize(){ $this->load->model('Email_message_model','messages');$r=$this->messages->summarize($this->body()['threadId']??'',$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Thread not found',404);}function triage(){ $this->load->model('Email_message_model','messages');$r=$this->messages->triage($this->body()['threadId']??'',$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Thread not found',404);}function dashboard(){ $this->load->model('Email_message_model','messages');return $this->respond($this->messages->dashboard($this->c['organizationId']));}function send($id){$this->load->model('Email_message_model','messages');$msg=$this->messages->one($id,$this->c['organizationId']);if(!$msg||$msg['direction']!=='outbound')return $this->fail('NOT_FOUND','Outbound message not found',404);$box=$this->mailboxes->raw($msg['mailboxId'],$this->c['organizationId']);if(!$box||!$box['smtp_host'])return $this->fail('VALIDATION_ERROR','SMTP mailbox is not configured',422);$config=array('protocol'=>'smtp','smtp_host'=>$box['smtp_host'],'smtp_port'=>$box['smtp_port']?:587,'smtp_user'=>$box['username'],'smtp_pass'=>$this->mailboxes->password($box['id'],$this->c['organizationId']),'smtp_timeout'=>10,'mailtype'=>$msg['bodyHtml']?'html':'text','charset'=>'utf-8','newline'=>"\r\n",'crlf'=>"\r\n");if(in_array((int)$config['smtp_port'],array(465,587),TRUE))$config['smtp_crypto']=(int)$config['smtp_port']===465?'ssl':'tls';$this->load->library('email',$config);$this->email->from($box['email_address'],$box['name'])->to($msg['to'])->cc($msg['cc'])->subject($msg['subject'])->message($msg['bodyHtml']?:$msg['bodyText']);$ok=$this->email->send(FALSE);$debug=$ok?'SMTP accepted message':strip_tags($this->email->print_debugger(array('headers')));$r=$this->messages->delivery($id,$this->c['organizationId'],$ok,$debug,$ok?NULL:$debug);return $ok?$this->respond($r):$this->fail('SMTP_DELIVERY_FAILED','SMTP delivery fail